{{ get_solua_print_css() }}{% set p = get_wholesale_print_data(doc) %}{% set show_images = 1 if doc.get('custom_print_color_images') is none else doc.get('custom_print_color_images') %}{% set show_item_name = 1 if doc.get('custom_print_item_name') is none else doc.get('custom_print_item_name') %}{% set show_sku = 1 if doc.get('custom_print_sku') is none else doc.get('custom_print_sku') %}{% set show_color_code = 1 if doc.get('custom_print_color_code') is none else doc.get('custom_print_color_code') %}{% set show_cor = 1 if doc.get('custom_print_cor') is none else doc.get('custom_print_cor') %}{% set show_description = 1 if doc.get('custom_print_description') is none else doc.get('custom_print_description') %}
<style>
  .wholesale-title { text-align: center; margin-bottom: 18px; }
  .wholesale-meta { width: 100%; margin-bottom: 14px; }
  .wholesale-items { width: 100%; border-collapse: collapse; table-layout: auto; }
  .wholesale-items th, .wholesale-items td { border: 1px solid #d1d8dd; padding: var(--solua-cell-padding); vertical-align: middle; }
  .wholesale-items th { background: #f5f7f9; }
  .wholesale-image { width: 42px; height: 42px; object-fit: cover; }
  .wholesale-qr-list { display: flex; gap: 18px; flex-wrap: wrap; margin-top: 18px; }
  .wholesale-qr { display: flex; align-items: center; gap: 7px; }
  .wholesale-qr img { width: 62px; height: 62px; }
</style>
<h2 class='wholesale-title'>Venda por atacado / 批发销售单</h2>
<table class='wholesale-meta'>
  <tr><td><b>Cliente / 客户</b>：{{ doc.customer_name or doc.customer }}</td><td><b>Data / 日期</b>：{{ doc.posting_date }}</td></tr>
  <tr><td><b>N.º / 单号</b>：{{ doc.name }}</td><td><b>Moeda / 币种</b>：{{ doc.currency }}</td></tr>
</table>
<table class='wholesale-items'>
  <thead><tr>{% if show_images %}<th>Foto / 图片</th>{% endif %}{% if show_item_name %}<th class="col-item">{{ _('Artigo / 商品') }}</th>{% endif %}{% if show_sku %}<th class="col-sku">{{ _('SKU / 货号') }}</th>{% endif %}{% if show_color_code %}<th class="col-color-code">Código de cor fixo / 固定色号</th>{% endif %}{% if show_cor %}<th class="col-cor">{{ _('Cor / 颜色') }}</th>{% endif %}<th class="col-barcode">{{ _('条码 / Código de barras') }}</th>{% if show_description %}<th class="col-description">{{ _('描述 / Descrição') }}</th>{% endif %}<th class="col-qty">Quantidade / 数量</th><th class="col-uom">Unidade / 单位</th><th class="col-rate">Preço unitário /<br>单价</th><th class="col-amount">Valor / 金额</th></tr></thead>
  <tbody>
  {% for item in p['items'] %}
    <tr>{% if show_images %}<td>{% if item.image %}<img class='wholesale-image' src='{{ item.image | e }}' alt='{{ item.color | e }}'>{% endif %}</td>{% endif %}{% if show_item_name %}<td>{{ item.item_name | e }}</td>{% endif %}{% if show_sku %}<td class="col-sku">{{ item.order_code or item.item_code | e }}</td>{% endif %}{% if show_color_code %}<td class="col-color-code">{{ item.color_code | e }}</td>{% endif %}{% if show_cor %}<td class="col-cor">{{ item.color | e }}</td>{% endif %}<td class="col-barcode">{{ item.barcode | e }}</td>{% if show_description %}<td class="col-description">{{ item.description | e }}</td>{% endif %}<td style='text-align:right'>{{ format_print_qty(item.qty) }}</td><td class="col-uom">{{ item.uom | e }}</td><td style='text-align:right'>{{ format_print_money(item.rate, currency=doc.currency) }}</td><td style='text-align:right'>{{ format_print_money(item.amount, currency=doc.currency) }}</td></tr>
  {% endfor %}
  </tbody>
  <tfoot><tr><td colspan='{{ 1 + show_images + show_item_name + show_sku + show_color_code + show_cor + show_description }}' style='text-align:right'><b>Total Qty / 总数量</b></td><td style='text-align:right'><b>{{ format_print_qty(get_print_total_qty(p)) }}</b></td><td colspan='3'></td></tr><tr><td colspan='{{ 4 + show_images + show_item_name + show_sku + show_color_code + show_cor + show_description }}' style='text-align:right'><b>Total / 合计</b></td><td style='text-align:right'><b>{{ format_print_money(doc.grand_total, currency=doc.currency) }}</b></td></tr></tfoot>
</table>
{% if doc.get('custom_print_color_qr') %}
  {% set seen = [] %}
  <div class='wholesale-qr-list'><b>Cartela de cores / 色卡：</b>
  {% for item in p['items'] %}
    {% if item.template_code and item.template_code not in seen %}
      {% set _ = seen.append(item.template_code) %}
      {% set qr = get_color_card_qr_img(item.template_code) %}
      {% if qr %}<div class='wholesale-qr'><img src='{{ qr }}' alt='QR'><span>{{ item.template_code }}</span></div>{% endif %}
    {% endif %}
  {% endfor %}
  </div>
{% endif %}

css:
.print-format table.items, .print-format table.wholesale-items { table-layout: auto; }
.print-format table.items th, .print-format table.items td,
.print-format table.wholesale-items th, .print-format table.wholesale-items td { overflow-wrap: normal; word-break: normal; }
.print-format .items .col-item { min-width: 24mm; }
.print-format .items .col-sku { min-width: 27mm; white-space: nowrap; }
.print-format .items .col-color-code, .print-format .items .col-cor { min-width: 16mm; white-space: nowrap; }
.print-format .items .col-barcode { min-width: 31mm; white-space: nowrap; }
.print-format .items .col-description { min-width: 42mm; white-space: normal; overflow-wrap: break-word; word-break: normal; }
.print-format .items .col-qty, .print-format .items .col-uom,
.print-format .items .col-rate, .print-format .items .col-amount { white-space: nowrap; }

.print-format .items .col-item, .print-format .wholesale-items .col-item { min-width: 24mm; }
.print-format .items .col-sku, .print-format .wholesale-items .col-sku { min-width: 27mm; white-space: nowrap; }
.print-format .items .col-color-code, .print-format .items .col-cor,
.print-format .wholesale-items .col-color-code, .print-format .wholesale-items .col-cor { min-width: 16mm; white-space: nowrap; }
.print-format .items .col-barcode, .print-format .wholesale-items .col-barcode { min-width: 31mm; white-space: nowrap; }
.print-format .items .col-description, .print-format .wholesale-items .col-description { min-width: 42mm; white-space: normal; overflow-wrap: break-word; word-break: normal; }
.print-format .items .col-qty, .print-format .items .col-uom, .print-format .items .col-rate, .print-format .items .col-amount,
.print-format .wholesale-items .col-qty, .print-format .wholesale-items .col-uom, .print-format .wholesale-items .col-rate, .print-format .wholesale-items .col-amount { white-space: nowrap; }
